      q3: '【정답 해설】 ①번. 묘안은 일을 잘 해결할 수 있는 좋은 생각이나 방법이고, 배짱은 겁내지 않고 맞서는 용기나 담력이다.\n【오답 해설】 ②번: 묘안은 실패한 계획이 아니라 좋은 방법이며, 배짱은 두려워하는 마음이 아니라 용기이다. ③번: 묘안은 나쁜 의도가 아니며, 배짱은 도망치는 행동이 아니라 맞서는 용기이다. ④번: 묘안은 평범한 생각이 아니라 뛰어난 방법이며, 배짱은 슬픈 감정이 아니라 담력이다.',
      q4: '【정답 해설】 ③번. 본문에서 텔이 "만약 제 아들을 다치게 했다면, 이 화살로 당신을 쏘았을 겁니다"라고 말했다.\n【오답 해설】 ①번: 화살이 부러질 것을 대비한 것이 아니라, 아들이 다치면 총독을 쏘려고 준비한 것이다. ②번: 총독은 사과 두 개를 맞히라고 한 적이 없고, 아들 머리 위의 사과 한 개만 맞히라고 했다. ④번: 텔은 활 솜씨를 자랑하려 한 것이 아니라, 아들을 보호하려는 마음에서 두 번째 화살을 준비했다.'
