      '<b>미시시피 강</b>가의 작은 마을에 <b>허클베리 핀</b>이라는 소년이 살았어요. 헉이라 불리는 이 소년은 술주정뱅이 아버지 밑에서 <b>자유</b>롭지 못한 답답한 생활을 견디고 있었지요. 아버지는 매일 술에 취해 어린 헉을 마구 때리고, 학교에도 보내 주지 않았어요. 헉은 인자한 더글러스 과부 댁에서 잠시 살면서 한글과 셈을 익히는 <b>교육</b>을 받기도 했지만, 빳빳한 옷을 입고 깐깐한 <b>예의범절</b>을 강요받는 것이 답답하기만 했어요. 그러던 어느 날 돌아온 아버지는 헉의 돈을 빼앗기 위해 그를 깊은 숲속 외딴 오두막에 가두어 버렸지요. 무자비한 폭력에 시달리던 헉은 더 이상 견딜 수 없어 마침내 도망치기로 결심했어요. 헉은 동물의 피로 자신이 죽은 것처럼 현장을 꾸미고 직접 만든 작은 <b>뗏목</b>을 타고 어두운 강으로 떠났어요. 강 위에서 헉은 도망친 흑인 <b>노예</b> <b>짐</b>을 만났어요. 짐은 자유로운 북부 주(州)로 가서 헤어진 가족을 되찾고 싶어 했지요.',
