      q2: '【정답 풀이】 1문단에서 왕자와 거지가 똑같은 얼굴로 만나 옷을 바꿔 입고, 2문단에서 에드워드가 거리에서 백성들의 고통을 직접 겪으며, 3문단에서 톰이 백성을 위한 좋은 법을 만들기 시작하고, 4문단에서 대관식에서 국새의 위치를 말해 진짜 왕자임을 증명함을 설명한다.\n[오답 풀이] ②번은 2문단과 3문단 내용이 바뀌었다. ③번은 1문단과 2문단, 3문단과 4문단 내용이 바뀌었다. ④번은 2문단과 4문단 내용이 바뀌었다.',
      q3: '【정답 해설】 ②번. 왕자는 임금의 아들이고, 거지는 빌어먹으며 떠도는 가난한 사람이다.\n【오답 해설】 ①번: 왕자는 가난한 사람이 아니라 임금의 아들이며, 거지는 부자가 아니라 가난한 사람이다. ③번: 왕자는 상인의 아들이 아니며, 거지는 농부가 아니다. ④번: 왕자는 선생님이 아니며, 거지는 학생이 아니다.',
      q4: '【정답 해설】 ④번. 본문에서 에드워드는 왕이 된 후에도 거지로 살았던 경험을 잊지 않고 "신분에 관계없이 모든 백성을 공정하게 대하는 현명한 왕이 되었다"고 명시되어 있다.\n【오답 해설】 ①번: 왕자의 삶이 무조건 좋다는 것을 깨달은 것이 아니다. ②번: 거지의 삶이 더 재미있다는 내용은 본문에 없다. ③번: 옷이 사람을 결정한다는 것이 아니라, 신분보다 마음이 중요하다는 것을 깨달았다.'
