    passage: [
      '캔자스의 농장에 사는 소녀 도로시는 엠 이모, 헨리 삼촌과 함께 단조롭게 살고 있었어요. 어느 날 들판 너머에서 갑자기 불어온 무시무시한 <b>회오리바람</b>에 도로시는 집째로 휩쓸려 신비한 오즈의 나라에 뚝 떨어져 도착했어요. 마침 떨어진 집에 사악한 동쪽 마녀가 깔려 그 자리에서 죽고 말았고, 도로시는 자신도 모르는 사이에 먼치킨 나라 사람들을 오랜 압제에서 구한 <b>영웅</b>이 되었어요. 착한 마녀 글린다로부터 신비한 마법의 루비 구두를 선물로 받은 도로시는 그리운 집으로 어떻게든 돌아가고 싶었어요. 글린다는 멀리 에메랄드 성에 사는 위대한 오즈의 <b>마법사</b>만이 도와줄 수 있다고 했지요. 도로시는 충직한 강아지 토토와 함께 끝없이 펼쳐진 <b>노란벽돌 길</b>을 따라 머나먼 모험을 시작했답니다. 처음 가는 낯선 땅에서의 <b>여행</b>은 무척 두렵기도 했지만, 도로시는 마음속 <b>희망</b>을 잃지 않았어요.',
      '긴 여행 도중에 도로시는 정말 특별한 친구들을 차례로 만났어요. 들판에 외로이 서 있던 <b>허수아비</b>는 머리에 뇌가 없어서 똑똑해지고 싶어 했고, 숲속의 녹슨 <b>양철 나무꾼</b>은 가슴에 심장이 없어서 따뜻한 사랑을 느끼고 싶어 했어요. 덩치 큰 겁쟁이 사자는 누구보다 용기가 없어서 씩씩하고 당당해지고 싶었지요. 네 친구는 각자의 간절한 소원을 이루기 위해 함께 빛나는 에메랄드 성으로 향했어요. 도중에 무서운 서쪽 마녀가 날아다니는 원숭이들을 보내 그들을 끈질기게 위협했지만, 친구들은 서로 <b>협동</b>하며 모든 어려움을 함께 이겨냈어요. 특히 허수아비는 지혜로운 계책을 척척 내고, 양철 나무꾼은 누구보다 따뜻한 마음으로 친구들을 감싸 주고, 겁쟁이 사자는 의외로 용감하게 앞장섰답니다. 각자 자신에게 부족한 것이 있다고 생각했지만, 사실 그들은 이미 그것을 마음속에 모두 가지고 있었어요.',
      '마침내 빛나는 에메랄드 성에 도착한 도로시 일행은 오즈의 위대한 마법사가 사실은 마법이라곤 한 줌도 없는 평범한 사람임을 알게 되었어요. 커튼 뒤에 숨어 거대한 가짜 머리 모형을 조종하던 노인은 그저 멋진 <b>환상</b>을 만들어 낸 것이었지요. 하지만 자상한 마법사는 허수아비에게는 똑똑한 지혜의 <b>증표</b>를, 녹슨 양철 나무꾼에게는 따뜻한 사랑의 증표를, 그리고 겁쟁이 사자에게는 빛나는 용기의 증표를 한 사람씩 정성스레 주었어요. 사실 세 친구는 이미 그동안 함께 겪은 길고 험한 모험을 통해 그것들을 마음에 모두 갖고 있었지만 스스로는 미처 깨닫지 못했던 것이지요. 한편 오즈 마법사는 알록달록한 색색의 열기구를 타고 도로시와 함께 멀리 캔자스로 떠나려 했지만, 강아지 토토가 고양이를 쫓아 달려가면서 도로시는 그만 그 마지막 기회를 놓쳐 버렸어요. 도로시는 한순간 깊이 실망했지만, 곁을 지켜 주는 따뜻한 친구들이 있어 큰 <b>위로</b>를 받았답니다.',
      '그때 마침 착한 남쪽 마녀 글린다가 분홍빛 거품처럼 나타나 도로시에게 빛나는 루비 구두의 놀라운 비밀을 직접 알려주었어요. "사실 처음부터 집으로 돌아갈 마법의 힘이 너에게 있었단다. 하지만 네가 스스로 직접 <b>경험</b>해야만 했어." 도로시가 두 발꿈치를 세 번 톡톡 부딪치며 "집만큼 좋은 곳은 없어, 집만큼 좋은 곳은 없어"라고 진심으로 말하자, 도로시는 그토록 그리워하던 사랑하는 캔자스의 집으로 한순간에 돌아갔어요. 이 가슴 따뜻한 이야기는 우리가 그토록 멀리서 찾는 것이 이미 우리 마음 안에 있다는 것, 그리고 가장 소중한 것은 늘 가까이에 있다는 깊은 <b>교훈</b>을 주는 작품이에요. 도로시는 머나먼 오즈의 나라에서 만난 다정한 친구들과의 빛나는 추억을 영원히 가슴에 간직하며, 사랑하는 <b>가족</b>과 함께하는 일상의 소중함을 마음 깊이 새삼 깨달았답니다.'
    ],
