      q3: '【정답 해설】 ②번. 황야는 거칠고 황량한 들판이고, 비극은 슬프고 불행한 결말의 이야기다.\n【오답 해설】 ①번: 황야는 도시의 중심가가 아니라 거친 들판이며, 비극은 기쁜 일이 아니라 슬픈 일이다. ③번: 황야는 바다가 아니며, 비극은 코미디(희극)의 반대이다. ④번: 황야는 학교가 아니며, 비극은 축제가 아니다.',
