      '바다 한가운데서 산티아고는 드디어 거대한 청새치를 낚습니다. 물고기는 너무 커서 배보다 길었습니다. 물고기와 노인의 싸움이 시작됩니다. 청새치는 배를 끌고 바다를 달리고, 산티아고는 줄을 놓지 않습니다. 손에서 피가 나고, 허리가 아프고, <b>고통</b>스러워도 그는 버팁니다. 그는 물고기에게 말합니다. "너는 내가 본 가장 아름다운 것이다. 하지만 너를 죽여야 한다." 산티아고는 물고기를 <b>존경</b>하면서도 <b>사투</b>를 멈추지 않습니다.',
      '3일간의 치열한 싸움 끝에 산티아고는 청새치를 잡습니다. 그러나 기쁨도 잠시, 배로 돌아오는 길에 상어들이 청새치의 피 냄새를 맡고 몰려듭니다. 산티아고는 <b>작살</b>과 노, 심지어 키까지 사용해 상어와 싸웁니다. <b>인내</b>와 <b>의지</b>로 버텨보지만, 상어들은 계속 덤벼듭니다. 결국 청새치는 뼈만 남습니다. 그래도 노인은 "인간은 파괴될 수 있을지 몰라도, <b>패배</b>하지는 않는다"고 스스로에게 말합니다.',
