    passage: [
      '영국 작가 조지 오웰이 쓴 이 소설은 농장의 동물들이 인간 주인을 내쫓고 스스로 농장을 운영하는 이야기입니다. 늙은 수퇘지 메이저는 죽기 전 동물들에게 연설합니다. 인간은 동물을 <b>착취</b>할 뿐이니, <b>혁명</b>을 일으켜야 한다고 말하죠. 그는 "동물의 영국"이라는 꿈을 이야기하며, 자유와 풍요로움 속에서 살아가는 세상을 그렸어요. 메이저가 죽은 후 동물들은 정말로 농장 주인 존스를 쫓아내고 "동물농장"을 세웁니다. 그들의 슬로건은 "네 발은 좋고, 두 발은 나쁘다"였고, "모든 동물은 <b>평등</b>하다"는 원칙을 세웁니다. 돼지들은 가장 영리해서 글을 읽고 쓸 수 있었고, 자연스럽게 지도자 역할을 맡게 됩니다. 동물들은 처음에는 자신들이 이룬 <b>성취</b>에 기뻐하며 열심히 일했어요. 농장의 이름도 "매너 농장"에서 "동물농장"으로 바꾸고, 일곱 계명을 벽에 새겼답니다.',
      '혁명 초기에는 모든 동물이 열심히 일하고 함께 결정을 내렸습니다. 영리한 돼지들인 스노볼과 나폴레옹이 지도자가 됩니다. 스노볼은 풍차를 세워 농장을 발전시키자고 <b>제안</b>하며, 미래를 위한 청사진을 그렸어요. 그는 동물들에게 풍차가 완성되면 일주일에 사흘만 일하면 된다고 약속했지요. 그러나 곧 나폴레옹은 몰래 키운 개들을 풀어 스노볼을 쫓아내고 혼자 권력을 잡습니다. 나폴레옹과 돼지들은 점점 <b>특권</b>을 누리기 시작합니다. 농장의 우유와 사과를 독차지하고, 농장 집에서 살기 시작했어요. 다른 동물들은 더 열심히 일하지만 먹을 것은 줄어듭니다. 의문을 제기하면 개들에게 공격당합니다. 원래의 규칙들은 슬쩍 바뀌기 시작하고, 나폴레옹의 말은 곧 법이 되었어요. 동물들의 <b>희망</b>은 점점 사라져갔습니다.',
      '말 복서는 "나는 더 열심히 일하겠다"와 "나폴레옹은 항상 옳다"를 <b>신념</b>으로 삼고 누구보다 열심히 일합니다. 그는 성실하고 순박한 동물이었지만, 너무 순진했어요. 복서의 강한 힘은 농장을 지탱하는 버팀목이었지요. 하지만 나이가 들어 쓸모없어지자, 나폴레옹은 복서를 도살장에 팔아버립니다. 동물들에게는 병원에 보냈다고 <b>거짓말</b>하며, 복서가 죽어가면서도 혁명을 외쳤다고 속였어요. 실제로는 돈을 받고 도살업자에게 판 것이었지요. 돼지 스퀼러는 뛰어난 말솜씨로 다른 동물들을 속이고, 역사까지 <b>조작</b>합니다. "기억력이 나빠서 헷갈리는 거야"라고 말하며 동물들의 <b>의심</b>을 잠재웁니다. 스노볼이 사실은 <b>배신</b>자였고, 존스와 협력했다는 거짓 이야기까지 만들어냈어요.',
      '시간이 지나면서 돼지들은 인간처럼 행동합니다. 두 발로 걷고, 옷을 입고, 술을 마시고, 인간들과 거래하며 이익을 챙겼어요. 농장 집의 침대에서 자고, 라디오를 듣고, 신문을 읽었지요. 마지막에 동물들이 농장 건물 창문으로 들여다보자, 돼지와 인간이 함께 카드놀이를 하고 있습니다. 동물들은 돼지와 인간을 구별할 수 없게 됩니다. 원래의 "모든 동물은 평등하다"는 "모든 동물은 평등하다, 그러나 어떤 동물은 더 평등하다"로 바뀌어 있었습니다. 농장 이름도 다시 "매너 농장"으로 돌아갔어요. 혁명은 완전히 배신당했고, 동물들은 처음보다 더 힘든 삶을 살게 되었답니다. 이 소설은 권력의 <b>부패</b>와 <b>독재</b>의 위험성을 <b>풍자</b>하며, 실제 역사의 교훈을 담고 있습니다.'
    ],
