      '미국 작가 하퍼 리가 쓴 이 소설은 1930년대 미국 남부 앨라배마 주의 작은 마을을 배경으로 합니다. 화자는 여덟 살 소녀 스카웃(진 루이스 핀치)입니다. 스카웃은 오빠 젬과 함께 변호사인 아버지 애티커스 핀치 밑에서 자랍니다. 어머니는 일찍 돌아가셨고, 가정부 칼푸르니아가 아이들을 돌봐주었어요. 애티커스는 마을에서 <b>존경</b>받는 사람이지만, 흑인 청년 톰 로빈슨을 변호하기로 하면서 상황이 달라집니다. 톰은 백인 여성을 <b>폭행</b>했다는 혐의를 받고 있었습니다. 하지만 애티커스는 진실을 위해 이 사건을 맡기로 합니다. 마을 사람들은 애티커스를 비난하기 시작했고, 스카웃과 젬도 학교에서 놀림을 받았답니다.',
