      '그러나 시간이 지나면서 상황이 바뀝니다. 아이들 중 일부가 어둠 속에 "<b>야수</b>"가 있다고 두려워하기 시작합니다. 사실 야수는 없었지만, <b>공포</b>는 점점 커져갔어요. 잭과 사냥꾼들은 점점 사냥의 흥분에 빠지고, <b>야만적</b>으로 변해갑니다. 얼굴에 칠을 하고, "야수를 죽여라!"를 외치며 춤을 춥니다. 처음에는 돼지를 잡지 못하던 잭이 점점 잔인해졌어요. <b>본능</b>이 이성을 이기기 시작한 것입니다. 잭은 랠프의 리더십에 <b>반발</b>하여 자기 무리를 따로 만듭니다. 많은 소년들이 잭에게 넘어갑니다. 잭은 고기를 제공했고, 아이들은 먹을 것을 위해 그를 따랐어요. 피기와 랠프만 남아 질서를 지키려 하지만, 힘없는 <b>소수</b>였답니다.',
      '비극이 시작됩니다. 어느 밤 <b>광란</b>의 춤판에서 소년들은 시몬이라는 착한 아이를 야수로 착각하여 죽입니다. 시몬은 "야수"의 정체가 사실 죽은 낙하산병이라는 <b>진실</b>을 알려주려다 죽은 것입니다. 폭풍우가 몰아치는 밤, 흥분한 아이들은 시몬을 창과 몽둥이로 공격했어요. 이후 잭의 무리가 피기마저 바위로 쳐서 죽이고 소라껍데기도 부숩니다. 규칙과 <b>문명</b>의 상징이 모두 파괴된 것입니다. 잭의 무리는 이제 완전히 야만인이 되었고, <b>폭력</b>이 지배하는 세상이 되었답니다.',
