// ✅ 세계문학(2) 콘텐츠 로드 완료 이벤트 발생
console.log('[deep_world2_content.js] CONTENTS 등록 완료, world2_01 존재:', !!window.CONTENTS.world2_01);
window.WORLD2_CONTENT_LOADED = true;
window.dispatchEvent(new CustomEvent('world2ContentLoaded'));

/* ===============================
   ★ 어휘 빈칸 렌더러 & 탭 이벤트
=================================*/
function getCurrentUnit() {
  return (window.CUR_UNIT || 'world2_01');
}

if (typeof _vocabFillRendered === "undefined") var _vocabFillRendered = false;

window.renderVocabFill = function () {
  // 이미 렌더링되었으면 다시 렌더링하지 않음 (탭 전환 시 상태 유지)
  if (_vocabFillRendered) {
    console.log('[renderVocabFill] 이미 렌더링됨, 건너뛰기');
    return;
  }
  const unit = window.CUR_UNIT || 'world2_01';
  const pack = window.CONTENTS?.[unit];
  const root = document.getElementById('vocab-fill')
            || document.querySelector('.vocab-fill-text');

  if (!root || !pack?.vocabFill?.items?.length) {
    console.warn('[vocab] root or items missing:', { root: !!root, unit, items: pack?.vocabFill?.items?.length });
    return;
}

  // ✅ 이미 렌더링된 경우 다시 렌더링하지 않음 (탭 전환 시 채점 결과 유지)
  const existingBlanks = root.querySelectorAll('.blank-wrap');
  if (existingBlanks.length > 0) {
    console.log('[renderVocabFill] 이미 렌더링됨 - 스킵 (채점 결과 유지)');
    return;
}

  const html = (pack.vocabFill.items || []).map(({ no, text, answer, initials }) => {
    const slot = `
      <span class="blank-wrap" data-answer="${answer}">
        <span class="blank-icon">${no}</span>
        <span class="blank-mark"></span>
        <input type="text" class="blank-input" placeholder="${initials || ''}">
      </span>
    `;
    const p = text.replace(/\(\s*[-＿—\u00A0]*\s*\)/, slot);
    return `<p>${p}</p>`;
  }).join('');

  root.innerHTML = `
    <div class="vocab-instruction">${pack.vocabFill.instructions || ''}</div>
    <div class="vocab-inline">${html}</div>
  `;


  // 렌더링 완료 표시
  _vocabFillRendered = true;

  (function ensureVocabInlineStyle(){
    if (document.getElementById('vocab-inline-style')) return;
    const st = document.createElement('style');
    st.id = 'vocab-inline-style';
    st.textContent = `
      .vocab-box .vocab-inline > p { display:inline !important; margin:0 !important; }
      .vocab-box .vocab-inline > p + p::before { content:" "; }
      #vocab-fill .vocab-inline > p,
      .vocab-fill-text .vocab-inline > p { display:inline !important; margin:0 !important; }
      #vocab-fill .vocab-inline > p + p::before,
      .vocab-fill-text .vocab-inline > p + p::before { content:" "; }
      .vocab-inline { line-height: 5.0 !important; }
    `;
    document.head.appendChild(st);
  })();

  window.reportState = window.reportState || {};
  window.reportState.vocabTotal = pack.vocabFill.items.length;

  // ✅ 어휘 렌더링 직후 상태 복원
  setTimeout(() => {
    // 1. localStorage에서 복원
    if (typeof window.loadVocabState === 'function') {
      window.loadVocabState();
  }
    // 2. 서버 데이터가 있으면 서버 데이터로 복원 (우선순위 높음)
    if (typeof window.restoreVocabFromServerData === 'function') {
      window.restoreVocabFromServerData();
  }
  }, 100);
};

if (typeof _tabEventsInitialized === "undefined") var _tabEventsInitialized = false;
function _bindTabEvents() {
  if (_tabEventsInitialized) return;
  _tabEventsInitialized = true;
  document.addEventListener('click', (e)=>{
    const btn = e.target.closest('[data-tab]');
    if (!btn) return;
    const tab = btn.getAttribute('data-tab');
    if (tab === 'vocab') renderVocabFill();
  });
}

/* ===== 텍스트 주입 ===== */
function applyContentPack(unitKey) {
  console.log('[applyContentPack] 호출됨, unitKey:', unitKey);
  const pack = window.CONTENTS[unitKey];
  if (!pack) {
    console.error('[applyContentPack] pack이 없음! unitKey:', unitKey);
    return;
}

  const labelNoEl = document.querySelector('.passage-label strong');
  const titleEl   = document.querySelector('.passage-title');
  if (labelNoEl) labelNoEl.textContent = pack.labelNo;
  if (titleEl)   titleEl.innerHTML = pack.title;

  const passageBox = document.querySelector('.passage-text');
  if (passageBox) {
    const wrapSentences = (text) => {
      const tagPlaceholders = [];
      let protectedText = text.replace(/<[^>]+>/g, (match) => { tagPlaceholders.push(match); return `__TAG_${tagPlaceholders.length - 1}__`; });
      const sentences = protectedText.split(/(?<=[.?!])(?=\s|$)/);
      return sentences.map(sentence => { const trimmed = sentence.trim(); if (!trimmed) return ''; let restored = trimmed.replace(/__TAG_(\d+)__/g, (_, idx) => tagPlaceholders[parseInt(idx)]); return `<span class="sentence">${restored}</span>`; }).join(' ');
    };
    passageBox.innerHTML = pack.passage.map(p => `<p>${wrapSentences(p)}</p>`).join('');

    if (!document.getElementById('sentence-hover-style')) {
      const style = document.createElement('style'); style.id = 'sentence-hover-style';
      style.textContent = `.passage-text .sentence { cursor: pointer; transition: background-color 0.15s ease, font-weight 0.15s ease; border-radius: 3px; padding: 1px 0; } .passage-text .sentence:hover { background-color: rgba(211, 90, 26, 0.12); font-weight: 600; } .passage-text .sentence.selected { background-color: rgba(211, 90, 26, 0.2); font-weight: 600; }`;
      document.head.appendChild(style);
    }
    const unitKey = window.CUR_UNIT || 'deep_world2_01';
    const stuForStorage = getCurrentStudentForReading();
    const studentSuffix = stuForStorage ? `_${stuForStorage.grade}_${stuForStorage.name}` : '';
    const storageKey = `passage_read_${unitKey}${studentSuffix}`;
    const saved = localStorage.getItem(storageKey); const selectedSet = new Set(saved ? JSON.parse(saved) : []);
    const allSentences = passageBox.querySelectorAll('.sentence');
    allSentences.forEach((span, idx) => { if (selectedSet.has(idx)) span.classList.add('selected'); });

    // 읽기 시간 기록용 - 학생별로 구분
    const timeKey = `passage_time_${unitKey}${studentSuffix}`; let readingStartTime = null; const savedTime = localStorage.getItem(timeKey);
    if (savedTime) { const parsed = JSON.parse(savedTime); readingStartTime = parsed.start ? new Date(parsed.start) : null; if (parsed.duration) { const clockMinutes = Math.floor(parsed.duration / 60000); const clockSeconds = Math.floor((parsed.duration % 60000) / 1000); const minInput = document.getElementById('minute-input'); const secInput = document.getElementById('second-input'); if (minInput) minInput.value = String(clockMinutes).padStart(2, '0'); if (secInput) secInput.value = String(clockSeconds).padStart(2, '0'); } }
    const formatDateTime = (date) => { const m = date.getMonth() + 1; const d = date.getDate(); const h = date.getHours(); const min = date.getMinutes().toString().padStart(2, '0'); return `${m}월 ${d}일 ${h}:${min}`; };
    const formatDuration = (ms) => { const totalSec = Math.floor(ms / 1000); const minutes = Math.floor(totalSec / 60); const seconds = totalSec % 60; return `${minutes}분 ${seconds}초`; };

    // 문단별 완료 상태 추적
    const paragraphs = passageBox.querySelectorAll('p');
    const paragraphCompletedKey = `paragraph_completed_${unitKey}${studentSuffix}`;
    const savedParagraphCompleted = localStorage.getItem(paragraphCompletedKey);
    const paragraphCompletedSet = new Set(savedParagraphCompleted ? JSON.parse(savedParagraphCompleted) : []);

    // 문단 중심 내용 팝업 스타일
    if (!document.getElementById('paragraph-popup-style')) {
      const pps = document.createElement('style'); pps.id = 'paragraph-popup-style';
      pps.textContent = `.paragraph-popup-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 10000; display: flex; align-items: center; justify-content: center; } .paragraph-popup { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%); background: #fff; border-radius: 16px; padding: 24px; max-width: 500px; width: 90%; max-height: 85vh; overflow-y: auto; box-shadow: 0 10px 40px rgba(0,0,0,0.3); z-index: 10001; } @keyframes popupIn { from { opacity: 0; transform: scale(0.9); } to { opacity: 1; transform: scale(1); } } .paragraph-popup-title { font-size: 18px; font-weight: bold; color: #333; margin-bottom: 16px; text-align: center; } .paragraph-popup-options { display: flex; flex-direction: column; gap: 10px; } .paragraph-popup-option { padding: 14px 16px; border: 2px solid #e0e0e0; border-radius: 10px; cursor: pointer; font-size: 16px; line-height: 1.5; transition: all 0.2s; background: #fafafa; } .paragraph-popup-option:hover { border-color: #ff6f35; background: #fff5f0; } .paragraph-popup-option.correct { border-color: #4caf50; background: #e8f5e9; } .paragraph-popup-option.wrong { border-color: #f44336; background: #ffebee; } .paragraph-popup-feedback { margin-top: 16px; padding: 12px; border-radius: 8px; text-align: center; font-weight: bold; } .paragraph-popup-feedback.correct { background: #e8f5e9; color: #2e7d32; } .paragraph-popup-feedback.wrong { background: #ffebee; color: #c62828; }`;
      document.head.appendChild(pps);
    }

    // 문단 중심 내용 팝업 함수
    function showParagraphPopup(paragraphIndex, onComplete, onWrong) {
      if (!pack.paragraphMain || !pack.paragraphMain[paragraphIndex]) { onComplete(); return; }
      const correctAnswer = pack.paragraphMain[paragraphIndex];
      const allOptions = [...pack.paragraphMain];
      for (let i = allOptions.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [allOptions[i], allOptions[j]] = [allOptions[j], allOptions[i]]; }
      const overlay = document.createElement('div'); overlay.className = 'paragraph-popup-overlay';
      const popup = document.createElement('div'); popup.className = 'paragraph-popup';
      popup.innerHTML = `<div class="paragraph-popup-title">📖 방금 읽은 ${paragraphIndex + 1}번째 문단의 중심 내용을 골라주세요</div><div class="paragraph-popup-options">${allOptions.map((opt, i) => `<div class="paragraph-popup-option" data-idx="${i}">${opt}</div>`).join('')}</div>`;
      overlay.appendChild(popup); document.body.appendChild(overlay); popup.style.top = (window.innerHeight / 2) + 'px'; popup.style.left = (window.innerWidth / 2) + 'px';
      const options = popup.querySelectorAll('.paragraph-popup-option');
      options.forEach(opt => {
        opt.addEventListener('click', () => {
          const selectedText = opt.textContent; const isCorrect = selectedText === correctAnswer;
          if (isCorrect) {
            opt.classList.add('correct'); options.forEach(o => o.style.pointerEvents = 'none');
            const feedback = document.createElement('div'); feedback.className = 'paragraph-popup-feedback correct'; feedback.textContent = '정답입니다! 👏'; popup.appendChild(feedback);
            if (!document.getElementById('fall-keyframes')) { const fk = document.createElement('style'); fk.id = 'fall-keyframes'; fk.textContent = '@keyframes fall { 0% { opacity: 1; transform: translateY(0) rotate(0deg); } 100% { opacity: 0; transform: translateY(100vh) rotate(360deg); } }'; document.head.appendChild(fk); }
      // confetti 종이 꽃가루 효과
      if (typeof window.playSubmitCelebration === 'function') { window.playSubmitCelebration(); }
            for (let i = 0; i < 12; i++) { const sparkle = document.createElement('div'); sparkle.textContent = ['✨','🎉','⭐','🌟','💫','🎊'][Math.floor(Math.random()*6)]; Object.assign(sparkle.style, { position: 'fixed', left: Math.random()*100 + 'vw', top: '-30px', fontSize: (16 + Math.random()*12) + 'px', zIndex: 10001, pointerEvents: 'none', animation: `fall ${1.5 + Math.random()*1}s ease-out forwards` }); document.body.appendChild(sparkle); setTimeout(() => sparkle.remove(), 2500); }
            setTimeout(() => { overlay.remove(); onComplete(); }, 1200);
          } else {
            opt.classList.add('wrong');
            // ★ 중심문단 퀴즈 오답 기록
            if (typeof window.recordParagraphQuizError === 'function') {
              window.recordParagraphQuizError(paragraphIndex + 1);
            }
            options.forEach(o => o.style.pointerEvents = 'none');
            const existingFeedback = popup.querySelector('.paragraph-popup-feedback'); if (existingFeedback) existingFeedback.remove();
            // 큰 X 표시 추가
            const wrongMark = document.createElement('div');
            wrongMark.textContent = '❌';
            wrongMark.style.cssText = 'font-size: 80px; text-align: center; margin: 20px 0; animation: shake 0.5s ease;';
            if (!document.getElementById('shake-keyframes')) { const sk = document.createElement('style'); sk.id = 'shake-keyframes'; sk.textContent = '@keyframes shake { 0%, 100% { transform: translateX(0); } 20%, 60% { transform: translateX(-10px); } 40%, 80% { transform: translateX(10px); } }'; document.head.appendChild(sk); }
            popup.appendChild(wrongMark);
            const feedback = document.createElement('div'); feedback.className = 'paragraph-popup-feedback wrong'; feedback.textContent = '다시 읽고 문단중심내용을 찾아주세요'; popup.appendChild(feedback);
            // 3초 후 팝업 닫고 해당 문단 문장 해제
            setTimeout(() => {
              overlay.remove();
              // 해당 문단의 모든 문장 선택 해제
              const currentParagraphs = passageBox.querySelectorAll('p');
              if (currentParagraphs[paragraphIndex]) {
                const sentencesInParagraph = currentParagraphs[paragraphIndex].querySelectorAll('.sentence');
                sentencesInParagraph.forEach(s => s.classList.remove('selected'));
                // localStorage 업데이트
                const allSentences = passageBox.querySelectorAll('.sentence');
                const selectedIndices = [];
                allSentences.forEach((s, i) => { if (s.classList.contains('selected')) selectedIndices.push(i); });
                localStorage.setItem(storageKey, JSON.stringify(selectedIndices));
              }
              onWrong(paragraphIndex);
            }, 3000);
          }
        });
      });
    }

    // 완독 축하 팝업 함수
    function showCompletionToast() {
      const endTime = new Date(); const duration = endTime - readingStartTime;
      localStorage.setItem(timeKey, JSON.stringify({ start: readingStartTime.toISOString(), end: endTime.toISOString(), duration: duration }));
      const stu = getCurrentStudentForReading(); if (stu) { const studentKey = buildStudentKeyForReading(stu); const unitKeyForSave = window.CUR_UNIT || 'unknown'; fetch('/api/reading-time', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ studentKey, unitKey: unitKeyForSave, duration, startTime: readingStartTime.toISOString(), endTime: endTime.toISOString() }) }).catch(err => console.error('독해시간 저장 실패:', err)); }
      const clockMinutes = Math.floor(duration / 60000); const clockSeconds = Math.floor((duration % 60000) / 1000); const minInputUpdate = document.getElementById('minute-input'); const secInputUpdate = document.getElementById('second-input'); if (minInputUpdate) minInputUpdate.value = String(clockMinutes).padStart(2, '0'); if (secInputUpdate) secInputUpdate.value = String(clockSeconds).padStart(2, '0');
      if (!document.getElementById('toast-style')) { const ts = document.createElement('style'); ts.id = 'toast-style'; ts.textContent = `.toast-pop { position: fixed; top: 50%; left: 50%; transform: translate(-50%, -50%) scale(0.7); background: linear-gradient(135deg, #ff9a56 0%, #ff6f35 100%); color: #fff; padding: 32px 60px; border-radius: 20px; font-size: 1.8rem; font-weight: bold; z-index: 9999; opacity: 0; animation: toastAnim 4s ease forwards; box-shadow: 0 10px 40px rgba(255,111,53,0.4); text-align: center; } @keyframes toastAnim { 0% { opacity: 0; transform: translate(-50%, -50%) scale(0.7); } 15% { opacity: 1; transform: translate(-50%, -50%) scale(1.1); } 30% { transform: translate(-50%, -50%) scale(1); } 85% { opacity: 1; } 100% { opacity: 0; transform: translate(-50%, -50%) scale(0.9); } }`; document.head.appendChild(ts); }
      const toast = document.createElement('div'); toast.className = 'toast-pop'; toast.innerHTML = `지문 완독! 대단해요!<div style="font-size:16px;margin-top:12px;color:rgba(255,255,255,0.9);line-height:1.6;"><div>시작: ${formatDateTime(readingStartTime)}</div><div>완료: ${formatDateTime(endTime)}</div><div style="margin-top:8px;font-weight:bold;">총 독해시간: ${formatDuration(duration)}</div></div>`; document.body.appendChild(toast); setTimeout(() => toast.remove(), 4100);
      for (let i = 0; i < 18; i++) { const sparkle = document.createElement('div'); sparkle.textContent = ['✨','🎉','⭐','🌟','💫','🎊'][Math.floor(Math.random()*6)]; Object.assign(sparkle.style, { position: 'fixed', left: Math.random()*100 + 'vw', top: '-30px', fontSize: (18 + Math.random()*16) + 'px', zIndex: 9998, pointerEvents: 'none', animation: `fall ${2 + Math.random()*1.5}s ease-out forwards` }); document.body.appendChild(sparkle); setTimeout(() => sparkle.remove(), 3500); }
      if (!document.getElementById('fall-keyframes')) { const fk = document.createElement('style'); fk.id = 'fall-keyframes'; fk.textContent = '@keyframes fall { 0% { opacity: 1; transform: translateY(0) rotate(0deg); } 100% { opacity: 0; transform: translateY(100vh) rotate(360deg); } }'; document.head.appendChild(fk); }
      // confetti 종이 꽃가루 효과
      if (typeof window.playSubmitCelebration === 'function') { window.playSubmitCelebration(); }
    }

    passageBox.addEventListener('click', e => {
      const span = e.target.closest('.sentence'); if (!span) return;
      if (!readingStartTime) { readingStartTime = new Date(); localStorage.setItem(timeKey, JSON.stringify({ start: readingStartTime.toISOString() })); }
      const currentSentences = passageBox.querySelectorAll('.sentence');
      const idx = Array.from(currentSentences).indexOf(span);
      span.classList.toggle('selected');
      const selectedIndices = []; currentSentences.forEach((s, i) => { if (s.classList.contains('selected')) selectedIndices.push(i); });
      localStorage.setItem(storageKey, JSON.stringify(selectedIndices));
      const total = currentSentences.length;
      const selected = passageBox.querySelectorAll('.sentence.selected').length;
      if (selected === 0) { const minInput = document.getElementById('minute-input'); const secInput = document.getElementById('second-input'); if (minInput) minInput.value = '00'; if (secInput) secInput.value = '00'; readingStartTime = null; localStorage.removeItem(timeKey); paragraphCompletedSet.clear(); localStorage.removeItem(paragraphCompletedKey); }

      const currentParagraph = span.closest('p');
      const currentParagraphs = passageBox.querySelectorAll('p');
      const paragraphIdx = Array.from(currentParagraphs).indexOf(currentParagraph);

      if (!span.classList.contains('selected') && paragraphCompletedSet.has(paragraphIdx)) {
        paragraphCompletedSet.delete(paragraphIdx);
        localStorage.setItem(paragraphCompletedKey, JSON.stringify([...paragraphCompletedSet]));
      }
      if (paragraphIdx >= 0 && !paragraphCompletedSet.has(paragraphIdx)) {
        const sentencesInParagraph = currentParagraph.querySelectorAll('.sentence');
        const selectedInParagraph = currentParagraph.querySelectorAll('.sentence.selected');
        if (sentencesInParagraph.length > 0 && sentencesInParagraph.length === selectedInParagraph.length) {
          paragraphCompletedSet.add(paragraphIdx);
          localStorage.setItem(paragraphCompletedKey, JSON.stringify([...paragraphCompletedSet]));
          const isLastParagraph = (paragraphIdx === currentParagraphs.length - 1);
          const isFullyCompleted = (total > 0 && total === selected);
          const handleWrong = (pIdx) => { paragraphCompletedSet.delete(pIdx); localStorage.setItem(paragraphCompletedKey, JSON.stringify([...paragraphCompletedSet])); };
          if (isLastParagraph && isFullyCompleted) {
            showParagraphPopup(paragraphIdx, () => { showCompletionToast(); }, handleWrong);
          } else {
            showParagraphPopup(paragraphIdx, () => { if (isFullyCompleted) { showCompletionToast(); } }, handleWrong);
          }
        }
      } else if (total > 0 && total === selected) {
        showCompletionToast();
      }
    });
}

  const vocabBox = document.querySelector('.passage-vocab ol');
  if (vocabBox) vocabBox.innerHTML = pack.vocab.map(([w,d]) => `<li><b>${w}</b>: ${d}</li>`).join('');

  const blocks = Array.from(document.querySelectorAll('#tab-reading .quiz-block'));

  // 완독 전 문제풀이 차단
  blocks.forEach(block => {
    block.addEventListener('click', (e) => {
      if (e.target.closest('input[type="radio"], label, .quiz-options li')) {
        const totalSentences = passageBox.querySelectorAll('.sentence').length;
        const selectedSentences = passageBox.querySelectorAll('.sentence.selected').length;
        if (totalSentences > 0 && selectedSentences < totalSentences) {
          e.preventDefault();
          e.stopPropagation();
          if (!document.getElementById('reading-alert-style')) { const s = document.createElement('style'); s.id = 'reading-alert-style'; s.textContent = '.reading-alert-overlay { position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); display: flex; align-items: center; justify-content: center; z-index: 99999; } .reading-alert-box { background: white; padding: 32px 48px; border-radius: 16px; text-align: center; box-shadow: 0 10px 40px rgba(0,0,0,0.3); animation: alertPop 0.3s ease; } .reading-alert-box p { font-size: 16px; color: #333; margin: 0 0 20px 0; line-height: 1.6; } .reading-alert-btn { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; border: none; padding: 12px 36px; border-radius: 25px; font-size: 15px; cursor: pointer; font-weight: 600; } .reading-alert-btn:hover { transform: scale(1.05); } @keyframes alertPop { from { opacity: 0; transform: scale(0.8); } to { opacity: 1; transform: scale(1); } }'; document.head.appendChild(s); } const overlay = document.createElement('div'); overlay.className = 'reading-alert-overlay'; overlay.innerHTML = '<div class="reading-alert-box"><p>지문의 모든 문장을 클릭하여<br>완독 후 문제풀이가 가능합니다</p><button class="reading-alert-btn">확인</button></div>'; document.body.appendChild(overlay); overlay.querySelector('.reading-alert-btn').onclick = () => overlay.remove(); overlay.onclick = (ev) => { if (ev.target === overlay) overlay.remove(); };
          return false;
        }
      }
    }, true);
  });

  if (blocks[0]) {
    const q1Text = blocks[0].querySelector('.quiz-q');
    const q1Lis  = blocks[0].querySelectorAll('.quiz-options li');
    if (q1Text) q1Text.innerHTML = pack.quiz.q1_text;
    if (q1Lis.length === 4) {
      q1Lis.forEach((li,i)=> li.innerHTML = `<label><input type="radio" name="q1" value="${i+1}"><span>${pack.quiz.q1_opts[i]}</span></label>`);
  }
}

  if (blocks[1]) {
    const q2Text = blocks[1].querySelector('.quiz-q');
    const q2Lis  = blocks[1].querySelectorAll('.quiz-options li');
    if (q2Text) q2Text.innerHTML = pack.quiz.q2_text;
    if (q2Lis.length === 4) {
      q2Lis.forEach((li,i)=> li.innerHTML = `<label><input type="radio" name="q2" value="${i+1}"><span>${pack.quiz.q2_opts[i]}</span></label>`);
  }
}

  if (blocks[2]) {
    const q3P = blocks[2].querySelector('.quiz-q');
    if (q3P && pack.quiz.q3_html) q3P.innerHTML = pack.quiz.q3_html;
    const q3_1 = document.getElementById('q3-1');
    const q3_2 = document.getElementById('q3-2');
    if (q3_1 && pack.quiz.q3_1_ph) q3_1.placeholder = pack.quiz.q3_1_ph;
    if (q3_2 && pack.quiz.q3_2_ph) q3_2.placeholder = pack.quiz.q3_2_ph;
}

  if (blocks[3]) {
    const q4P = blocks[3].querySelector('.quiz-q');
    if (q4P && pack.quiz.q4_html) q4P.innerHTML = pack.quiz.q4_html;
    const q4_1 = document.getElementById('q4-1');
    const q4_2 = document.getElementById('q4-2');
    if (q4_1 && pack.quiz.q4_1_ph) q4_1.placeholder = pack.quiz.q4_1_ph;
    if (q4_2 && pack.quiz.q4_2_ph) q4_2.placeholder = pack.quiz.q4_2_ph;
}

  if (blocks[4]) {
    const q5Text = blocks[4].querySelector('.quiz-q');
    if (q5Text && pack.quiz.q5_text) q5Text.textContent = pack.quiz.q5_text;
}

  // ✅ 모든 콘텐츠 로드 완료 후 로딩 오버레이 숨기기
  requestAnimationFrame(() => {
    const loadingOverlay = document.getElementById('loadingOverlay');
    if (loadingOverlay) {
      // 분석리포트 탭일 경우 1.3초 후에 숨기기
      const unit = window.CUR_UNIT || 'world2_01';
      const savedTab = localStorage.getItem(`current-geo-tab:${unit}`);
      const delay = (savedTab === 'report') ? 1300 : 0;

      setTimeout(() => {
        loadingOverlay.classList.remove('show');
        console.log('[applyContentPack] 로딩 오버레이 숨김 완료');
      }, delay);
  }
  });
}

/* ==== 본문학습 상태 저장/복원 ==== */
function getCurrentStudentForReading() {
  const saved = localStorage.getItem('currentStudent');
  if (!saved) return null;
  try { return JSON.parse(saved); } catch (e) { return null; }
}

function buildStudentKeyForReading(stu) {
  const cleanPhone = (stu.phone || '').replace(/\D/g, '');
  const cleanName  = (stu.name  || '').trim();
  const cleanGrade = (stu.grade || '').trim();
  return `${cleanGrade}_${cleanName}_${cleanPhone}`;
}

window.getStudentKey = function () {
  const stu = getCurrentStudentForReading();
  if (!stu) return '';
  return buildStudentKeyForReading(stu);
};

function getReadingStateKey(unit) {
  const stu = getCurrentStudentForReading();
  if (!stu) return `dan-reading-state:${unit}`;
  const studentKey = buildStudentKeyForReading(stu);
  return `dan-reading-state:${studentKey}:${unit}`;
}

function saveReadingState() {
  try {
    const unit = window.CUR_UNIT || 'world2_01';
    const key  = getReadingStateKey(unit);
    const q1   = document.querySelector('input[name="q1"]:checked');
    const q2   = document.querySelector('input[name="q2"]:checked');
    const q3_1 = document.getElementById('q3-1');
    const q3_2 = document.getElementById('q3-2');
    const q4_1 = document.getElementById('q4-1');
    const q4_2 = document.getElementById('q4-2');
    const q5   = document.getElementById('q5');
    const state = {
      graded: true,
      q1: q1 ? q1.value : '',
      q2: q2 ? q2.value : '',
      q3_1: q3_1 ? q3_1.value : '',
      q3_2: q3_2 ? q3_2.value : '',
      q4_1: q4_1 ? q4_1.value : '',
      q4_2: q4_2 ? q4_2.value : '',
      q5: q5 ? q5.value : ''
    };
    localStorage.setItem(key, JSON.stringify(state));
  } catch (e) { console.warn('saveReadingState error', e); }
}

function loadReadingState() {
  try {
    const unit = window.CUR_UNIT || 'world2_01';
    const key  = getReadingStateKey(unit);
    const raw  = localStorage.getItem(key);
    if (!raw) return;
    const state = JSON.parse(raw);
    if (!state) return;
    if (state.q1) {
      const r1 = document.querySelector(`input[name="q1"][value="${state.q1}"]`);
      if (r1) r1.checked = true;
  }
    if (state.q2) {
      const r2 = document.querySelector(`input[name="q2"][value="${state.q2}"]`);
      if (r2) r2.checked = true;
  }
    const q3_1 = document.getElementById('q3-1');
    const q3_2 = document.getElementById('q3-2');
    const q4_1 = document.getElementById('q4-1');
    const q4_2 = document.getElementById('q4-2');
    const q5   = document.getElementById('q5');
    if (q3_1 && state.q3_1 !== undefined) q3_1.value = state.q3_1;
    if (q3_2 && state.q3_2 !== undefined) q3_2.value = state.q3_2;
    if (q4_1 && state.q4_1 !== undefined) q4_1.value = state.q4_1;
    if (q4_2 && state.q4_2 !== undefined) q4_2.value = state.q4_2;
    if (q5 && state.q5 !== undefined) q5.value = state.q5;
    if (state.graded && typeof window.gradeQuiz === 'function') {
      setTimeout(() => { try { window.gradeQuiz(); } catch (e) { console.warn('auto re-grade error', e); } }, 0);
  }
  } catch (e) { console.warn('loadReadingState error', e); }
}

/* ===== 통합 채점기 ===== */
window.gradeQuiz = function () {
  const pack = window.CONTENTS[window.CUR_UNIT] || window.CONTENTS.world2_01;
  const A = pack.answerKey;
  const EX = pack.explain;

  const quizBlocks = document.querySelectorAll('#tab-reading .quiz-block');
  const numLabels = ["01","02","03","04","05"];
  quizBlocks.forEach((block, idx) => {
    const numEl = block.querySelector('.quiz-num');
    if (!numEl) return;
    let markEl = numEl.querySelector('.mark');
    if (!markEl) {
      markEl = document.createElement('div');
      markEl.className = 'mark';
      numEl.appendChild(markEl);
  }
    numEl.textContent = numLabels[idx];
    numEl.appendChild(markEl);
    numEl.classList.remove('correct','wrong');
    markEl.textContent = '';
  });

  let score = 0;
  const totalAuto = 4;
  const shortMsgs = [];
  const fullMsgs = [];

  function norm(s){ return (s||'').toString().replace(/\s+/g,'').toLowerCase(); }
  function mark(idx, ok, label, ex, isEssay=false){
    const num = quizBlocks[idx]?.querySelector('.quiz-num');
    const markEl = num?.querySelector('.mark');
    if (ok) {
      score++;
      num?.classList.add('correct');
      if(markEl) markEl.textContent='⭕';
      shortMsgs.push(`${label} 정답 ✅`);
      fullMsgs.push(`${label} 정답 ✅ ${ex||''}`);
    } else {
      num?.classList.add('wrong');
      if(markEl) markEl.textContent='✖';
      // ★ 5문제 오답 기록
      if (typeof window.recordProblemError === 'function') {
        window.recordProblemError(idx + 1);
      }
      shortMsgs.push(`${label} ${isEssay?'서술형: ':''}오답 ❌`);
      fullMsgs.push(`${label} ${isEssay?'서술형: ':''}오답 ❌ ${ex||''}`);
  }
}

  const q1 = document.querySelector('input[name="q1"]:checked');
  const q1ok = (q1 && q1.value === A.q1);
  mark(0, q1ok, '①', EX.q1);

  const q2 = document.querySelector('input[name="q2"]:checked');
  const q2ok = (q2 && q2.value === A.q2);
  mark(1, q2ok, '②', EX.q2);

  // 3번: 객관식(q3) 또는 주관식(q3_1, q3_2) 처리
  let q3ok = false;
  if (A.q3) {
    // 객관식
    const q3 = document.querySelector('input[name="q3"]:checked');
    q3ok = (q3 && q3.value === A.q3);
  } else if (A.q3_1) {
    // 주관식
    const q3New = document.getElementById('q3');
    const q3Old1 = document.getElementById('q3-1');
    const q3Old2 = document.getElementById('q3-2');
    const q3Text1 = q3New ? q3New.value.trim() : (q3Old1?.value || '').trim();
    const q3Text2 = q3New ? '' : (q3Old2?.value || '').trim();
    const ok3_1 = A.q3_1.some(a => norm(a) === norm(q3Text1));
    const ok3_2 = A.q3_2 ? A.q3_2.some(a => norm(a) === norm(q3Text2)) : true;
    q3ok = ok3_1 && ok3_2;
}
  mark(2, q3ok, '③', EX.q3);

  // 4번: 객관식(q4) 또는 주관식(q4_1, q4_2) 처리
  let q4ok = false;
  if (A.q4) {
    // 객관식
    const q4 = document.querySelector('input[name="q4"]:checked');
    q4ok = (q4 && q4.value === A.q4);
  } else if (A.q4_1) {
    // 주관식
    const q4New = document.getElementById('q4');
    const q4Old1 = document.getElementById('q4-1');
    const q4Old2 = document.getElementById('q4-2');
    const q4Text1 = q4New ? q4New.value.trim() : (q4Old1?.value || '').trim();
    const q4Text2 = q4New ? '' : (q4Old2?.value || '').trim();
    const ok4_1 = A.q4_1.some(a => norm(a) === norm(q4Text1));
    const ok4_2 = A.q4_2 ? A.q4_2.some(a => norm(a) === norm(q4Text2)) : true;
    q4ok = ok4_1 && ok4_2;
}
  mark(3, q4ok, '④', EX.q4);

  const essay = (document.getElementById('q5')?.value || '').trim().toLowerCase();
  const keys = (pack.essayKeywords && Array.isArray(pack.essayKeywords) && pack.essayKeywords.length)
    ? pack.essayKeywords : ["등고선","간격","좁","넓","급경사","완만","경사"];
  let hit = 0;
  keys.forEach(k => { if (essay.includes(k)) hit++; });
  const q5ok = essay.length && hit >= 2;
  mark(4, q5ok, '⑤', EX.q5, true);

  const box = document.getElementById('grade-result');
  if (box) {
    box.style.display = 'block';
    box.innerHTML = `<p><strong>점수: ${score} / ${totalAuto}</strong></p>` + shortMsgs.map(m => `<p>${m}</p>`).join('');
}
  window.fullResultHTML = `<p><strong>점수: ${score} / ${totalAuto}</strong></p>` + fullMsgs.map(m => `<p>${m}</p>`).join('');

  ['grade-btn','reset-btn','submit-btn'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.style.display='inline-block';
  });

  window.reportState = window.reportState || {};
  window.reportState.q1ok=q1ok;
  window.reportState.q2ok=q2ok;
  window.reportState.q3ok=q3ok;
  window.reportState.q4ok=q4ok;
  window.reportState.q5ok=q5ok;

  if (typeof updateReportPanel==='function') {
    const lexicalRatio = (typeof window.reportState.vocabScoreRatio==='number') ? window.reportState.vocabScoreRatio : 0;
    const lexicalOk = lexicalRatio >= 0.7;
    updateReportPanel({
      q1ok,q2ok,q3ok,q4ok,q5ok,
      messages:[
        "핵심 이해력: " + (q1ok?"좋아요! ✅":"보완 필요 ❗"),
        "구조 파악력: " + (q2ok?"좋아요! ✅":"보완 필요 ❗"),
        "어휘 맥락력: " + (lexicalOk?"좋아요! ✅":"어휘 복습 필요 ❗"),
        "추론·통합력: " + (q4ok?"좋아요! ✅":"보완 필요 ❗"),
        "비판·적용력: " + (q5ok?"좋아요! ✅":"보완 필요 ❗")
      ]
    });
}

  const radarScores = {
    literal: q1ok ? 10 : 6,
    structural: q2ok ? 10 : 6,
    lexical: q3ok ? 10 : 6,
    inferential: q4ok ? 10 : 6,
    critical: q5ok ? 10 : 6
  };
  window._lastRadar = radarScores;
  if (typeof updateRadarChart === 'function') updateRadarChart(radarScores);
  if (typeof drawRadarChart === 'function') drawRadarChart(radarScores);
  window.reportState.radarScores = radarScores;
  if (typeof saveReadingState === 'function') saveReadingState();
};

/* === 정답·해설 패널 렌더러 === */
function renderSolutions(pack) {
  const A = pack.answerKey, EX = pack.explain;
  const DT = pack.detail || {};
  const q1Text = pack.quiz.q1_opts[Number(A.q1) - 1] || '';
  const q2Text = pack.quiz.q2_opts[Number(A.q2) - 1] || '';

  const gradeResult = document.getElementById('grade-result');
  let box = document.getElementById('solutions-box');
  if (!box) {
    box = document.createElement('div');
    box.id = 'solutions-box';
    box.style.marginTop = '16px';
    box.style.background = '#fffaf3';
    box.style.border = '1px solid #e5d4c1';
    box.style.borderRadius = '12px';
    box.style.padding = '16px';
    box.style.lineHeight = '1.6';
}
  if (gradeResult) {
    gradeResult.appendChild(box);
}

  // 3번: 객관식(q3) 또는 빈칸(q3_1, q3_2) 형식 처리
  let q3Answer = '';
  if (A.q3 && pack.quiz.q3_opts) {
    const q3Text = pack.quiz.q3_opts[Number(A.q3) - 1] || '';
    q3Answer = `<b>정답:</b> ${A.q3} — ${q3Text}`;
  } else if (A.q3_1) {
    q3Answer = `<b>정답(두 칸):</b> ${Array.isArray(A.q3_1)?A.q3_1[0]:A.q3_1} / ${Array.isArray(A.q3_2)?A.q3_2[0]:A.q3_2}`;
}

  // 4번: 객관식(q4) 또는 빈칸(q4_1, q4_2) 형식 처리
  let q4Answer = '';
  if (A.q4 && pack.quiz.q4_opts) {
    const q4Text = pack.quiz.q4_opts[Number(A.q4) - 1] || '';
    q4Answer = `<b>정답:</b> ${A.q4} — ${q4Text}`;
  } else if (A.q4_1) {
    q4Answer = `<b>정답(두 칸):</b> ${Array.isArray(A.q4_1)?A.q4_1[0]:A.q4_1} / ${Array.isArray(A.q4_2)?A.q4_2[0]:A.q4_2}`;
}

  // detail 상세해설 헬퍼
  function buildExplainDetail(ex, dt) {
    let html = ex ? `<span style="color:#6b5a48;">${ex}</span>` : '';
    if (dt) html += `<br><span style="color:#2e7d32;">${dt}</span>`;
    return html;
}

  box.innerHTML = `
    <h3 style="margin:0 0 10px; font-size:16px; color:#8b2f2f;">정답 · 해설</h3>
    <ol style="margin:0; padding-left:18px;">
      <li style="margin-bottom:8px;">
        <b>정답:</b> ${A.q1} — ${q1Text}<br>
        ${buildExplainDetail(EX.q1, DT.q1)}
      </li>
      <li style="margin-bottom:8px;">
        <b>정답:</b> ${A.q2} — ${q2Text}<br>
        ${buildExplainDetail(EX.q2, DT.q2)}
      </li>
      <li style="margin-bottom:8px;">
        ${q3Answer}<br>
        ${buildExplainDetail(EX.q3, DT.q3)}
      </li>
      <li style="margin-bottom:8px;">
        ${q4Answer}<br>
        ${buildExplainDetail(EX.q4, DT.q4)}
      </li>
      <li>
        <b>서술형 예시:</b> <span style="color:#6b5a48;">${EX.q5 || '핵심어 2개 이상 포함 시 정답 처리'}</span>
      </li>
    </ol>
  `;
  box.style.display = 'block';
}

/* ========== 공통 진행도 매니저 ========== */
window.DanDan = window.DanDan || {};
(function () {
  if (window.DanDan.ProgressManager) return;

  function detectUnit() {
    let unitParam = new URLSearchParams(location.search).get('unit');
    if (!unitParam) {
      const m = location.pathname.match(/world2_(\d+)\.html/i);
      if (m) unitParam = `deep_world2_${m[1].padStart(2, '0')}`;
  }
    return (unitParam || (window.CUR_UNIT || 'world2_01')).toLowerCase();
}

  function buildStudentKey(stu) {
    const cleanPhone = (stu.phone || '').replace(/\D/g, '');
    const cleanName  = (stu.name  || '').trim();
    const cleanGrade = (stu.grade || '').trim();
    return `${cleanGrade}_${cleanName}_${cleanPhone}`;
}

  function getCurrentStudent() {
    const saved = localStorage.getItem('currentStudent');
    if (!saved) return null;
    try { return JSON.parse(saved); } catch { return null; }
}

  function buildProgressKey(stu, unit) {
    return `dan-progress:${buildStudentKey(stu)}:${unit}`;
}

  function readDoneList() {
    const stu = getCurrentStudent();
    if (!stu) return { keyPrefix: null, list: [] };
    const unitList = [];
    const studentKey = buildStudentKey(stu);
    const prefix = `dan-progress:${studentKey}:`;
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (!k || !k.startsWith(prefix)) continue;
      const unit = k.slice(prefix.length);
      const val  = localStorage.getItem(k);
      if (val) unitList.push(unit);
  }
    return { keyPrefix: prefix, list: unitList };
}

  const ProgressManager = {
    getUnit: detectUnit,
    markComplete() {
      const stu = getCurrentStudent();
      if (!stu) return null;
      const unit = detectUnit();
      const key  = buildProgressKey(stu, unit);
      const pageKey = `BRAINUP_worldlit_${unit}`;
      let saved = [];
      try {
        const existing = localStorage.getItem(key);
        if (existing) saved = JSON.parse(existing);
        if (!Array.isArray(saved)) saved = [];
      } catch(e) { saved = []; }
      if (!saved.includes(pageKey)) saved.push(pageKey);
      localStorage.setItem(key, JSON.stringify(saved));
      return key;
    },
    isCompleted(unitOptional) {
      const stu = getCurrentStudent();
      if (!stu) return false;
      const unit = (unitOptional || detectUnit());
      const key  = buildProgressKey(stu, unit);
      return !!localStorage.getItem(key);
    },
    getStudentProgress() { return readDoneList(); }
  };
  window.DanDan.ProgressManager = ProgressManager;

  (function hookSubmitReport() {
    const original = window.submitReport;
    window.submitReport = async function (...args) {
      const stu = getCurrentStudent();
      if (!stu) { alert('로그인한 학생 정보가 없습니다.'); return; }
      if (typeof original === 'function') {
        await original.apply(this, args);
      } else if (typeof window.captureElementToPDF === 'function') {
        await captureElementToPDF('capture-report', '단단국어_분석리포트.pdf', { withStudentInfo: true });
    }
      const key = ProgressManager.markComplete();
      if (typeof window.showSubmitSuccess === 'function') showSubmitSuccess('분석리포트');
      else console.log(`학습완료 처리됨: ${key}`);
      if (typeof window.sendLearningLog === 'function') {
        try { await window.sendLearningLog(); } catch (e) { console.warn('[submitReport] sendLearningLog 실패', e); }
    }
    };
  })();
})();

/* ===== 창의활동 제출 ===== */
window.submitCreative = async function () {
  const textarea   = document.getElementById('creative-input');
  const renderBox  = document.getElementById('creative-render');
  const captureBox = document.getElementById('capture-creative');
  if (!textarea || !renderBox || !captureBox) {
    alert('창의활동 영역을 찾을 수 없습니다.');
    return;
}
  try {
    renderBox.textContent = textarea.value || '';
    textarea.style.display  = 'none';
    renderBox.style.display = 'block';
    if (typeof window.captureElementToPDF === 'function') {
      await window.captureElementToPDF('capture-creative', '단단국어_창의활동.pdf', { withStudentInfo: true });
    } else if (window.html2canvas && window.jsPDF) {
      const canvas = await html2canvas(captureBox);
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const pageW = pdf.internal.pageSize.getWidth();
      const pageH = (canvas.height * pageW) / canvas.width;
      pdf.addImage(imgData, 'PNG', 0, 0, pageW, pageH);
      pdf.save('단단국어_창의활동.pdf');
    } else {
      alert('PDF 모듈을 찾을 수 없습니다.');
  }
    if (typeof window.showSubmitSuccess === 'function') window.showSubmitSuccess('창의활동');
  } catch (e) {
    console.warn('submitCreative error', e);
    alert('창의활동 PDF 생성 중 오류가 발생했습니다.');
  } finally {
    if (textarea)   textarea.style.display  = 'block';
    if (renderBox)  renderBox.style.display = 'none';
}
};

/* ===== 서버 완료 상태 동기화 ===== */
window.loadCompletionStatus = async function () {
  // ✅ 중복 호출 방지 - 이미 로딩 중이거나 완료된 경우 스킵
  if (window._completionStatusLoading) { console.log("[loadCompletionStatus] 이미 로딩 중 - 스킵"); return window._completionStatusPromise; }
  if (window._completionStatusLoaded) { console.log("[loadCompletionStatus] 이미 로드됨 - 스킵"); return; }
  window._completionStatusLoading = true;
  window._completionStatusPromise = (async () => {
  try {
    let stu = null;
    try {
      const raw = localStorage.getItem('currentStudent');
      if (raw) stu = JSON.parse(raw);
    } catch (e) { return; }
    if (!stu) return;
    const params = new URLSearchParams({ grade: stu.grade || '', name: stu.name || '', series: 'BRAIN딥' });
    const res = await fetch(`/api/completion-status?${params}`, { method: 'GET', headers: { 'Content-Type': 'application/json' } });
    if (!res.ok) return;
    const data = await res.json();
    if (data.ok && Array.isArray(data.completedUnits)) {
      const cleanPhone = (stu.phone || '').replace(/\D/g, '');
      const cleanName  = (stu.name  || '').trim();
      const cleanGrade = (stu.grade || '').trim();
      const studentKey = `${cleanGrade}_${cleanName}_${cleanPhone}`;
      const keyPrefix = `dan-progress:${studentKey}:`;
      data.completedUnits.forEach(unit => {
        try {
          const key = keyPrefix + unit;
          // 배열 형식으로 저장 (menu.html과 호환)
          let saved = [];
          try {
            const existing = localStorage.getItem(key);
            if (existing) {
              saved = JSON.parse(existing);
              if (!Array.isArray(saved)) saved = [];
          }
          } catch(e) { saved = []; }
          if (saved.length === 0) {
            saved.push('BRAINUP_worldlit_' + unit);
        }
          localStorage.setItem(key, JSON.stringify(saved));
        } catch(e) {
          // QuotaExceededError 등 무시하고 계속 진행
          console.warn('[loadCompletionStatus] 저장 실패 (용량 초과?):', unit, e.message);
      }
      });
  }
  } catch (e) { console.warn('[loadCompletionStatus] 오류', e);
  } finally {
    window._completionStatusLoading = false;
    window._completionStatusLoaded = true;
  }
  })();
  return window._completionStatusPromise;
};

window.sendLearningLog = async function () {
  try {
    const unit = window.ORIGINAL_UNIT || window.CUR_UNIT || 'world2_01';
    let stu = null;
    try {
      const raw = localStorage.getItem('currentStudent');
      if (raw) stu = JSON.parse(raw);
    } catch (e) { return; }
    if (!stu) return;
    // ✅ q1ok~q5ok로 레이더 점수 계산
    const rs = window.reportState || {};
    console.log('[sendLearningLog] 🔍 q1ok:', rs.q1ok, 'q2ok:', rs.q2ok, 'q3ok:', rs.q3ok, 'q4ok:', rs.q4ok, 'q5ok:', rs.q5ok);
    const radar = { literal: rs.q1ok ? 10 : 6, structural: rs.q2ok ? 10 : 6, lexical: rs.q3ok ? 10 : 6, inferential: rs.q4ok ? 10 : 6, critical: rs.q5ok ? 10 : 6 };
    console.log('[sendLearningLog] 🔍 계산된 radar:', JSON.stringify(radar));
    const payload = { grade: stu.grade || '', name: stu.name || '', school: stu.school || '', series: 'BRAIN딥', unit, radar, completed: true };
    const res = await fetch('/api/log', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(payload) });
    let data = {};
    try { data = await res.json(); } catch (_) {}
    console.log('[sendLearningLog] result =', data);
  } catch (e) { console.warn('sendLearningLog error', e); }
};

/* ===== DOMContentLoaded ===== */
document.addEventListener('DOMContentLoaded', async () => {
  // ⚡ 본문 즉시 표시 (서버 호출 백그라운드)
  applyContentPack(window.CUR_UNIT);
  if (typeof window.loadCompletionStatus === 'function') loadCompletionStatus();
  _bindTabEvents();
  if (location.hash.includes('어휘학습') || document.querySelector('#vocab-fill')) renderVocabFill();
  ['grade-btn','reset-btn','submit-btn'].forEach(id => {
    const el = document.getElementById(id);
    if (el) el.type = 'button';
  });
  const submitBtn = document.getElementById('submit-btn');
  if (submitBtn) {
    submitBtn.addEventListener('click', () => {
      try {
        if (typeof window.gradeQuiz === 'function') gradeQuiz();
        const pack = window.CONTENTS[window.CUR_UNIT] || window.CONTENTS.world2_01;
        renderSolutions(pack);
        // ★ 학습 행동 데이터 전송
        if (typeof window.sendLearningBehavior === 'function') {
          window.sendLearningBehavior();
        }
      } catch (e) { console.warn('submit-btn handler error', e); }
    });
}
  const creativeBtn = document.getElementById('creative-submit-btn');
  if (creativeBtn && typeof window.submitCreative === 'function') {
    creativeBtn.type = 'button';
    creativeBtn.addEventListener('click', () => submitCreative());
}
  if (typeof loadReadingState === 'function') loadReadingState();
});

// ✅ BRAINDEEP용 fit_ 키 매핑 (deep_world2_XX → world2_XX 데이터 참조)
(function() {
  for (let i = 1; i <= 40; i++) {
    const num = String(i).padStart(2, '0');
    const srcKey = `world2_${num}`;
    const fitKey = `deep_world2_${num}`;
    if (window.CONTENTS[srcKey] && !window.CONTENTS[fitKey]) {
      window.CONTENTS[fitKey] = window.CONTENTS[srcKey];
  }
}
})();

// ✅ 웹툰 힌트 숨기기 (중3/고1 딥 시리즈에서는 불필요)
(function() {
  const style = document.createElement('style');
  style.textContent = '.webtoon-hint-container { display: none !important; }';
  document.head.appendChild(style);
})();
